def load_ignore(dir_path):
    patterns = []
    for f in [".gitignore", ".ignore", ".agignore"]:
        p = os.path.join(dir_path, f)
        if os.path.exists(p):
            try:
                with open(p, "r", encoding="utf-8", errors="ignore") as file:
                    for line in file:
                        line = line.strip()
                        if line and not line.startswith("#"):
                            patterns.append(line)
            except:
                pass
    return patterns

def is_ignored(path, root, patterns):
    rel = os.path.relpath(path, root)
    parts = rel.split(os.sep)
    for pat in patterns:
        if pat.endswith("/"):
            if any(fnmatch.fnmatch(part + "/", pat) for part in parts):
                return True
        else:
            if any(fnmatch.fnmatch(part, pat) for part in parts):
                return True
        if fnmatch.fnmatch(rel, pat):
            return True
    return False

def build_regex(pattern, flags):
    if flags["literal"]:
        pattern = re.escape(pattern)
    if flags["word_regexp"]:
        pattern = r"\b" + pattern + r"\b"

    re_flags = 0
    if flags["smart_case"]:
        if not any(c.isupper() for c in pattern):
            re_flags |= re.IGNORECASE
    elif flags["ignore_case"]:
        re_flags |= re.IGNORECASE

    try:
        return re.compile(pattern, re_flags)
    except:
        return re.compile(re.escape(pattern), re_flags) # fallback if invalid regex

def format_match(line, matches, flags):
    if not flags["color"]:
        if flags["only_matching"]:
            return "\n".join(m.group() for m in matches)
        return line.rstrip("\n")

    # ANSI escape sequences
    C_MATCH = "\033[30;43m"
    C_RESET = "\033[0m"
    C_K = "\033[K"

    if flags["only_matching"]:
        return "\n".join(f"{C_MATCH}{m.group()}{C_RESET}{C_K}" for m in matches)

    # Highlight all matches in line
    res = []
    last = 0
    for m in matches:
        res.append(line[last:m.start()])
        res.append(f"{C_MATCH}{m.group()}{C_RESET}{C_K}")
        last = m.end()
    res.append(line[last:].rstrip("\n"))
    return "".join(res)

