{"command":"cat << 'EOF' >> ag.py
def search_file(file_path, regex, flags):
    matches_found = []
    try:
        if file_path == "-":
            f = sys.stdin
        else:
            f = open(file_path, "r", encoding="utf-8", errors="ignore")

        line_num = 1
        for line in f:
            if flags["invert_match"]:
                if not regex.search(line):
                    # For invert_match, there are no specific 'matches' to highlight usually,
                    # just the whole line.
                    matches_found.append((line_num, line, []))
            else:
                matches = list(regex.finditer(line))
                if matches:
                    matches_found.append((line_num, line, matches))
            line_num += 1
        if file_path != "-":
            f.close()
    except Exception as e:
        pass
    return matches_found

