import base64

HELP_B64 = "{help_b64}"
VERSION_B64 = "{ver_b64}"
FILE_TYPES_B64 = "{ft_b64}"

def parse_args():
    args = sys.argv[1:]
    flags = {{
        "ignore_case": False,
        "case_sensitive": False,
        "smart_case": True,
        "invert_match": False,
        "word_regexp": False,
        "literal": False,
        "count": False,
        "files_with_matches": False,
        "files_without_matches": False,
        "only_matching": False,
        "norecurse": False,
        "hidden": False,
        "unrestricted": False,
        "color": sys.stdout.isatty(),
        "filename": None,
        "numbers": None,
        "heading": sys.stdout.isatty(),
        "break_": sys.stdout.isatty(),
    }}

    if "--version" in args or "-V" in args:
        sys.stdout.write(base64.b64decode(VERSION_B64).decode('utf-8'))
        sys.exit(0)
    if "--list-file-types" in args:
        sys.stdout.write(base64.b64decode(FILE_TYPES_B64).decode('utf-8'))
        sys.exit(0)
    if "--help" in args:
        sys.stdout.write(base64.b64decode(HELP_B64).decode('utf-8'))
        sys.exit(0)

    paths = []
    pattern = None

    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-i", "--ignore-case"):
            flags["ignore_case"] = True
            flags["smart_case"] = False
        elif arg in ("-s", "--case-sensitive"):
            flags["case_sensitive"] = True
            flags["smart_case"] = False
        elif arg in ("-S", "--smart-case"):
            flags["smart_case"] = True
        elif arg in ("-v", "--invert-match"):
            flags["invert_match"] = True
        elif arg in ("-w", "--word-regexp"):
            flags["word_regexp"] = True
        elif arg in ("-Q", "--literal"):
            flags["literal"] = True
        elif arg in ("-c", "--count"):
            flags["count"] = True
        elif arg in ("-l", "--files-with-matches"):
            flags["files_with_matches"] = True
        elif arg in ("-L", "--files-without-matches"):
            flags["files_without_matches"] = True
        elif arg in ("-o", "--only-matching"):
            flags["only_matching"] = True
        elif arg in ("-n", "--norecurse"):
            flags["norecurse"] = True
        elif arg == "--hidden":
            flags["hidden"] = True
        elif arg in ("-u", "--unrestricted"):
            flags["unrestricted"] = True
        elif arg == "--color":
            flags["color"] = True
        elif arg == "--nocolor":
            flags["color"] = False
        elif arg == "--filename":
            flags["filename"] = True
        elif arg == "--nofilename":
            flags["filename"] = False
        elif arg == "--numbers":
            flags["numbers"] = True
        elif arg == "--nonumbers":
            flags["numbers"] = False
        elif arg == "--heading":
            flags["heading"] = True
        elif arg == "--noheading":
            flags["heading"] = False
        elif arg == "--break":
            flags["break_"] = True
        elif arg == "--nobreak":
            flags["break_"] = False
        elif arg in ("--nogroup", "--no-group"):
            flags["heading"] = False
            flags["break_"] = False
        elif not arg.startswith("-"):
            if pattern is None:
                pattern = arg
            else:
                paths.append(arg)
        i += 1

    if pattern is None:
        sys.stdout.write(base64.b64decode(HELP_B64).decode('utf-8'))
        sys.exit(1)

    if not paths:
        if not sys.stdin.isatty():
            paths = ["-"]
        else:
            paths = ["."]

    return pattern, paths, flags

def build_regex(pattern, flags):
    if flags["literal"]:
        pattern = re.escape(pattern)
    if flags["word_regexp"]:
        pattern = r"\\b" + pattern + r"\\b"

    re_flags = 0
    if flags["smart_case"]:
        if not any(c.isupper() for c in pattern):
            re_flags |= re.IGNORECASE
    elif flags["ignore_case"]:
        re_flags |= re.IGNORECASE

    try:
        return re.compile(pattern, re_flags)
    except:
        return re.compile(re.escape(pattern), re_flags)

def search_file(file_path, regex, flags):
    matches_found = []
    try:
        if file_path == "-":
            f = sys.stdin
        else:
            f = open(file_path, "r", encoding="utf-8", errors="ignore")

        line_num = 1
        for line in f:
            if flags["invert_match"]:
                if not regex.search(line):
                    matches_found.append((line_num, line, []))
            else:
                matches = list(regex.finditer(line))
                if matches:
                    matches_found.append((line_num, line, matches))
            line_num += 1
        if file_path != "-":
            f.close()
    except Exception as e:
        pass
    return matches_found

def format_match(line, matches, flags):
    if not flags["color"]:
        if flags["only_matching"] and not flags["invert_match"]:
            return "\\n".join(m.group() for m in matches)
        return line.rstrip("\\n")

    C_MATCH = "\\033[30;43m"
    C_RESET = "\\033[0m"
    C_K = "\\033[K"

    if flags["invert_match"]:
        return line.rstrip("\\n")

    if flags["only_matching"]:
        return "\\n".join(f"{{C_MATCH}}{{m.group()}}{{C_RESET}}{{C_K}}" for m in matches)

    res = []
    last = 0
    for m in matches:
        res.append(line[last:m.start()])
        res.append(f"{{C_MATCH}}{{m.group()}}{{C_RESET}}{{C_K}}")
        last = m.end()
    res.append(line[last:].rstrip("\\n"))
    return "".join(res)

def print_results(file_path, matches, flags, is_single_file, is_first_file):
    if not matches and not flags["files_without_matches"]:
        return False

    C_PATH = "\\033[1;32m"
    C_LINE = "\\033[1;33m"
    C_RESET = "\\033[0m"
    C_K = "\\033[K"

    def color_path(p):
        if flags["color"]: return f"{{C_PATH}}{{p}}{{C_RESET}}{{C_K}}"
        return p

    def color_num(n):
        if flags["color"]: return f"{{C_LINE}}{{n}}{{C_RESET}}{{C_K}}"
        return str(n)

    if flags["files_without_matches"]:
        if not matches:
            print(color_path(file_path))
            return True
        return False

    if flags["files_with_matches"]:
        print(color_path(file_path))
        return True

    if flags["count"]:
        match_count = sum(max(1, len(m[2])) for m in matches)
        if is_single_file and flags["filename"] is not True:
            print(color_num(match_count))
        else:
            print(f"{{color_path(file_path)}}:{{color_num(match_count)}}")
        return True

    print_filename = flags["filename"]
    if print_filename is None:
        if file_path == "-":
            print_filename = False
        else:
            print_filename = not is_single_file

    print_numbers = flags["numbers"]
    if print_numbers is None:
        print_numbers = (file_path != "-")

    if flags["only_matching"] and is_single_file:
        print_numbers = False

    if flags["heading"]:
        if not is_first_file and flags["break_"]:
            print()
        print(color_path(file_path))

    for line_num, line, line_matches in matches:
        out = ""
        if print_filename and not flags["heading"]:
            out += f"{{color_path(file_path)}}:"

        if print_numbers:
            out += f"{{color_num(line_num)}}:"

        formatted_line = format_match(line, line_matches, flags)
        if flags["only_matching"] and not flags["invert_match"]:
            parts = formatted_line.split("\\n")
            for p in parts:
                print(f"{{out}}{{p}}")
        else:
            print(f"{{out}}{{formatted_line}}")

    return True

def get_files(paths, flags):
    all_files = []
    for path in paths:
        if path == "-":
            all_files.append("-")
        elif os.path.isfile(path):
            all_files.append(path)
        elif os.path.isdir(path):
            for root, dirs, files in os.walk(path):
                if not flags["unrestricted"]:
                    if not flags["hidden"]:
                        dirs[:] = [d for d in dirs if not d.startswith(".")]
                        files = [f for f in files if not f.startswith(".")]
                for f in files:
                    all_files.append(os.path.join(root, f))
                if flags["norecurse"]:
                    break
    return all_files

def main():
    pattern, paths, flags = parse_args()
    regex = build_regex(pattern, flags)
    files = get_files(paths, flags)
    files.sort()

    is_single_file = (len(paths) == 1 and (paths[0] == "-" or os.path.isfile(paths[0])))

    any_match = False
    is_first_file = True
    for f in files:
        matches = search_file(f, regex, flags)
        if matches or flags["files_without_matches"]:
            if print_results(f, matches, flags, is_single_file, is_first_file):
                any_match = True
                is_first_file = False

    sys.exit(0 if any_match else 1)

if __name__ == "__main__":
    main()
